package migrate

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/spec-kitty/go-kitty3/internal/clock"
)

// Pre-commit hook installer (policy/hook_installer.py install()).
//
// The Go port pins the spec-kitty executable instead of a Python
// interpreter: the primary branch execs `<exe> commit-guard-hook`, the PATH
// fallback and the failure remedy are upstream's.

// HookSignature marks hooks spec-kitty generated.
const HookSignature = "# Generated by spec-kitty."

const hookTemplate = `#!/bin/sh
# Generated by spec-kitty. Do not edit by hand.
# Installed: {installed_at}
# Interpreter: {interpreter}
set -e
if [ -x "{interpreter}" ]; then
    exec "{interpreter}" commit-guard-hook "$@"
fi
if command -v spec-kitty >/dev/null 2>&1; then
    exec spec-kitty commit-guard-hook "$@"
fi
echo "[spec-kitty guard] Pinned interpreter is gone: {interpreter}" >&2
echo "[spec-kitty guard] 'spec-kitty' is also not on PATH." >&2
echo "[spec-kitty guard] Remedy: run 'spec-kitty migrate repin-hooks' from an environment where spec-kitty is installed and on PATH." >&2
exit 1
`

// HookInstall is HookInstallRecord.
type HookInstall struct {
	HookPath, Interpreter, BackupPath string
}

// InstallPreCommitHook writes <root>/.git/hooks/pre-commit (mode 0700),
// backing up a foreign pre-existing hook to pre-commit.<YYYYmmddTHHMMSSZ>.
func InstallPreCommitHook(root string) (*HookInstall, error) {
	exe, err := os.Executable()
	if err != nil {
		return nil, fmt.Errorf("Cannot install pre-commit hook: the spec-kitty executable cannot be located (%v).", err)
	}
	exe, _ = filepath.Abs(exe)
	if st, err := os.Stat(exe); err != nil || !st.Mode().IsRegular() {
		return nil, fmt.Errorf("Cannot install pre-commit hook: sys.executable=%s (absolute: %s) does not exist.", exe, exe)
	}
	now := clock.Now().UTC()
	rendered := strings.NewReplacer("{installed_at}", now.Format("2006-01-02T15:04:05+00:00"), "{interpreter}", exe).Replace(hookTemplate)
	hooks := filepath.Join(root, ".git", "hooks")
	if err := os.MkdirAll(hooks, 0o755); err != nil {
		return nil, err
	}
	hook := filepath.Join(hooks, "pre-commit")
	tmp, err := os.CreateTemp(hooks, "pre-commit.")
	if err != nil {
		return nil, err
	}
	tmpName := tmp.Name()
	_, werr := tmp.WriteString(rendered)
	tmp.Close()
	if werr != nil {
		os.Remove(tmpName)
		return nil, werr
	}
	os.Chmod(tmpName, 0o700)
	rec := &HookInstall{HookPath: hook, Interpreter: exe}
	if st, err := os.Lstat(hook); err == nil {
		b, rerr := os.ReadFile(hook)
		if rerr != nil || !strings.Contains(string(b), HookSignature) {
			side := hook + "." + now.Format("20060102T150405Z")
			if st.Mode()&os.ModeSymlink != 0 {
				target, _ := os.Readlink(hook)
				os.Symlink(target, side)
			} else {
				os.WriteFile(side, b, st.Mode().Perm())
			}
			rec.BackupPath = side
		}
	}
	if err := os.Rename(tmpName, hook); err != nil {
		os.Remove(tmpName)
		return nil, err
	}
	return rec, nil
}
